S = []
S.append(story("la_cena_del_dia_de_la_madre", "A1-2", "La cena del Día de la Madre",
 ("Ngày của Mẹ, bố Javier và hai con muốn tự nấu bữa tối. Nhưng bố chưa bao giờ vào bếp.", "On Mother's Day, Javier and his two children want to cook dinner themselves. But Javier never cooks."),
 ["papa", "cortar", "echar", "olvidar"],
 [("N", "Es el Día de la Madre.", "Hôm nay là Ngày của Mẹ.", "It is Mother's Day."),
  ("N", "Javier quiere preparar una cena para su mujer, Pilar.", "Javier muốn chuẩn bị một bữa tối cho vợ mình, chị Pilar.", "Javier wants to make dinner for his wife, Pilar."),
  ("N", "Pero Javier nunca cocina.", "Nhưng Javier chưa bao giờ nấu ăn.", "But Javier never cooks."),
  ("N", "Sus hijos, Pablo y Lola, deciden ayudar.", "Hai con của anh, Pablo và Lola, quyết định phụ bố.", "His children, Pablo and Lola, decide to help."),
  ("N", "Pilar está en casa de su madre. Ellos tienen dos horas.", "Chị Pilar đang ở nhà mẹ đẻ. Ba bố con có hai tiếng.", "Pilar is at her mother's. They have two hours."),
  ("B", "Vamos a hacer pollo con arroz y una sopa.", "Mình sẽ làm gà với cơm và một món súp.", "We're going to make chicken with rice and a soup."),
  ("A", "¿Sabes cocinar, papá?", "Bố có biết nấu ăn không?", "Can you cook, Dad?"),
  ("B", "No, pero voy a intentarlo.", "Không, nhưng bố sẽ thử xem.", "No, but I'm going to try."),
  ("N", "Lola corta el pollo. Pablo echa el arroz en el agua.", "Lola cắt thịt gà. Pablo cho gạo vào nước.", "Lola cuts up the chicken. Pablo puts the rice in the water."),
  ("N", "Javier prepara la sopa con huevo y queso.", "Javier nấu súp với trứng và phô mai.", "Javier makes the soup with egg and cheese."),
  ("N", "Los tres trabajan, hablan y se ríen.", "Ba bố con vừa làm vừa nói chuyện, cười đùa.", "The three of them work, talk and laugh."),
  ("N", "Pero Javier olvida el arroz.", "Nhưng Javier quên mất nồi cơm.", "But Javier forgets the rice."),
  ("A", "¡Papá, el arroz! ¡Ya no tiene agua!", "Bố ơi, cơm kìa! Cạn hết nước rồi!", "Dad, the rice! There's no water left!"),
  ("N", "Nadie puede comer ese arroz.", "Nồi cơm ấy chẳng ai ăn nổi.", "Nobody can eat that rice."),
  ("B", "¡No pasa nada! Hacemos otro.", "Không sao! Mình nấu nồi khác.", "Never mind! We'll make another."),
  ("N", "Pero ya no tienen arroz en casa.", "Nhưng trong nhà đã hết gạo.", "But there's no more rice in the house."),
  ("N", "En ese momento llega Pilar, una hora antes.", "Đúng lúc đó chị Pilar về, sớm hơn một tiếng.", "At that moment Pilar arrives, an hour early."),
  ("N", "Pilar mira la mesa, mira el arroz y mira a su familia.", "Chị Pilar nhìn cái bàn, nhìn nồi cơm rồi nhìn cả nhà.", "Pilar looks at the table, at the rice and at her family."),
  ("N", "Y empieza a reírse.", "Rồi chị phá lên cười.", "And she starts to laugh."),
  ("N", "La familia come pan, queso, fruta y la sopa de Javier.", "Thế là cả nhà ăn bánh mì, phô mai, trái cây và món súp của Javier.", "The family eats bread, cheese, fruit and Javier's soup."),
  ("N", "Pilar prueba la sopa y dice que le encanta.", "Chị Pilar nếm súp và bảo chị rất thích.", "Pilar tastes the soup and says she loves it."),
  ("B", "El próximo año, yo hago el pollo con arroz. ¡Lo prometo!", "Năm sau, bố sẽ làm món gà với cơm. Bố hứa đấy!", "Next year I'll make the chicken with rice. I promise!"),
  ("N", "Pilar se ríe. No le cree.", "Chị Pilar bật cười. Chị chẳng tin anh đâu.", "Pilar laughs. She doesn't believe him.")],
 [("locate", "Chị Pilar ở đâu khi ba bố con nấu ăn?", "Where is Pilar while the others cook?", [("Ở nhà mẹ đẻ", "At her mother's"), ("Ở chỗ làm", "At work"), ("Ở trong bếp", "In the kitchen")], 0),
  ("locate", "Chuyện gì xảy ra với nồi cơm?", "What happens to the rice?", [("Lola ăn hết", "Lola eats it all"), ("Nó bị cháy vì Javier quên", "It burns because Javier forgets it"), ("Pablo làm đổ", "Pablo spills it")], 1),
  ("infer", "Vì sao cuối truyện chị Pilar không tin lời hứa của Javier?", "Why doesn't Pilar believe Javier's promise at the end?", [("Vì anh ấy nấu ăn rất giỏi", "Because he is a very good cook"), ("Vì năm sau chị muốn tự nấu", "Because she wants to cook next year"), ("Vì Javier chưa bao giờ nấu ăn và lần này cũng làm cháy cơm", "Because Javier never cooks and this time he burnt the rice too")], 2)],
 names=["Javier", "Pilar", "Pablo", "Lola", "Día", "Madre"],
 token_map={"intentarlo": "es:w:intentar", "día": "es:w:dia", "madre": "es:w:madre", "prueba": "es:w:probar", "reírse": "es:w:reir"}))

S.append(story("el_coche_de_la_tia_rosa", "A1-2", "El coche de la tía Rosa",
 ("Dì Rosa chở Pablo và Lola lên núi. Giữa đường, xe hỏng.", "Aunt Rosa drives Pablo and Lola to the mountains. On the way, the car breaks down."),
 ["conducir", "arreglar", "aparecer", "romper"],
 [("N", "La tía Rosa lleva a Pablo y a Lola a un pueblo de la montaña.", "Dì Rosa đưa Pablo và Lola lên một ngôi làng trên núi.", "Aunt Rosa takes Pablo and Lola to a mountain village."),
  ("N", "Rosa conduce su coche por un camino largo.", "Dì Rosa lái xe trên một con đường dài.", "Rosa drives her car along a long road."),
  ("N", "Los niños miran la montaña por la ventana.", "Hai đứa trẻ ngắm núi qua cửa sổ.", "The children look at the mountain through the window."),
  ("N", "Tras una hora de viaje, el coche hace «¡pum!» y deja de funcionar.", "Đi được một tiếng thì chiếc xe kêu «bụp!» rồi chết máy.", "An hour into the trip, the car goes \"bang!\" and stops working."),
  ("A", "¡Ay, no! El coche está roto.", "Ôi, không! Xe hỏng rồi.", "Oh no! The car has broken down."),
  ("B", "¿Qué pasa, tía?", "Có chuyện gì thế dì?", "What's wrong, Auntie?"),
  ("A", "No sé. Voy a intentar arreglarlo.", "Dì không biết. Để dì thử sửa xem.", "I don't know. I'm going to try to fix it."),
  ("N", "Rosa intenta arreglar el coche durante una hora, pero no puede.", "Dì Rosa loay hoay sửa xe cả tiếng đồng hồ, nhưng không sửa được.", "Rosa tries to fix the car for an hour, but she can't."),
  ("N", "Pablo tiene hambre y Lola tiene sed.", "Pablo đói còn Lola thì khát.", "Pablo is hungry and Lola is thirsty."),
  ("N", "No pasa nadie por el camino.", "Chẳng có ai đi qua con đường.", "Nobody comes along the road."),
  ("B", "Tía, ¿vamos a vivir en este camino?", "Dì ơi, mình phải sống luôn trên con đường này à?", "Auntie, are we going to live on this road?"),
  ("A", "No, Pablo. Alguien va a venir. Ya verás.", "Không đâu, Pablo. Sẽ có người đến thôi. Rồi cháu xem.", "No, Pablo. Someone will come. You'll see."),
  ("N", "Y en unos minutos aparece un camión.", "Và chỉ vài phút sau, một chiếc xe tải xuất hiện.", "And within a few minutes a lorry appears."),
  ("N", "Un hombre baja del camión y pregunta: «¿Qué pasa? ¿Necesitan algo?»", "Một người đàn ông bước xuống xe tải và hỏi: «Có chuyện gì vậy? Mọi người có cần gì không?»", "A man climbs down from the lorry and asks: \"What's wrong? Do you need anything?\""),
  ("N", "El hombre mira el coche y lo arregla en diez minutos.", "Người đàn ông xem chiếc xe và sửa xong trong mười phút.", "The man looks at the car and fixes it in ten minutes."),
  ("A", "¡Gracias, señor!", "Cảm ơn anh nhiều!", "Thank you, sir!"),
  ("N", "El hombre dice adiós y vuelve a su camión.", "Người đàn ông chào tạm biệt rồi quay lại xe tải.", "The man says goodbye and goes back to his lorry."),
  ("N", "A las 8, Rosa, Pablo y Lola llegan al pueblo.", "Tám giờ tối, dì Rosa, Pablo và Lola đến được làng.", "At eight o'clock, Rosa, Pablo and Lola reach the village."),
  ("N", "En el hotel los espera un hombre. ¡Es el hombre del camión!", "Ở khách sạn có một người đàn ông đang đợi họ. Chính là người lái xe tải!", "At the hotel a man is waiting for them. It's the man from the lorry!"),
  ("N", "Él trabaja en el hotel. Les prepara una sopa y les enseña un mapa de la montaña.", "Anh ấy làm ở khách sạn. Anh nấu súp cho mọi người và chỉ cho họ tấm bản đồ vùng núi.", "He works at the hotel. He makes them a soup and shows them a map of the mountain."),
  ("A", "¿Ves, Pablo? En la montaña hay ángeles.", "Thấy chưa, Pablo? Trên núi có thiên thần đấy.", "See, Pablo? There are angels in the mountains.")],
 [("locate", "Chiếc xe của dì Rosa bị sao?", "What happens to Aunt Rosa's car?", [("Nó bị hỏng giữa đường", "It breaks down on the way"), ("Nó hết xăng ở khách sạn", "It runs out of petrol at the hotel"), ("Nó bị mất", "It is lost")], 0),
  ("locate", "Ai sửa chiếc xe?", "Who fixes the car?", [("Dì Rosa", "Aunt Rosa"), ("Pablo", "Pablo"), ("Người đàn ông lái xe tải", "The man with the lorry")], 2),
  ("infer", "Dì Rosa muốn nói gì khi bảo «trên núi có thiên thần»?", "What does Aunt Rosa mean by 'there are angels in the mountains'?", [("Rằng người đàn ông ấy đã giúp họ rất tốt bụng", "That the man helped them so kindly"), ("Rằng cô thấy thiên thần trên bản đồ", "That she saw angels on the map"), ("Rằng khách sạn có tên là Thiên Thần", "That the hotel is called The Angel")], 0)],
 names=["Rosa", "Pablo", "Lola"],
 token_map={"pregunta": "es:w:preguntar", "espera": "es:w:esperar", "tía": "es:w:tio", "arreglarlo": "es:w:arreglar", "pum": "function", "roto": "es:w:romper", "verás": "es:w:ver"}))

S.append(story("la_voz_de_la_abuela", "A2-1", "La voz de la abuela",
 ("Ban nhạc của Nico sắp diễn ở lễ hội làng thì cô ca sĩ mất giọng. Người cứu nguy là bà nội 75 tuổi.", "Nico's band is about to play at the village festival when the singer loses her voice. The rescuer is his 75-year-old grandmother."),
 ["voz", "oportunidad", "escenario", "miembro"],
 [("N", "Nico tiene 17 años y una banda con tres amigos de su calle.", "Nico 17 tuổi và có một ban nhạc với ba người bạn cùng phố.", "Nico is 17 and has a band with three friends from his street."),
  ("N", "La banda se llama Los Locos. Nico escribe sus propias canciones, y su amiga Eva es la voz.", "Ban nhạc tên là Những Kẻ Điên. Nico tự viết bài hát, còn cô bạn Eva là giọng ca chính.", "The band is called Los Locos. Nico writes his own songs, and his friend Eva is the voice."),
  ("N", "Un día reciben una oportunidad única: tocar en la fiesta del pueblo, delante de 1.000 personas.", "Một ngày nọ, cả nhóm nhận được một cơ hội có một không hai: biểu diễn ở lễ hội làng, trước một nghìn người.", "One day they get a unique chance: to play at the village festival, in front of a thousand people."),
  ("B", "Tenemos que estar a otro nivel. Vamos a tocar todos los días hasta la fiesta.", "Bọn mình phải lên một tầm khác. Ngày nào cũng tập cho đến hôm lễ hội.", "We have to be on another level. We're going to play every day until the festival."),
  ("N", "Durante dos semanas tocan cada tarde en casa de Nico.", "Suốt hai tuần, chiều nào cả nhóm cũng tập ở nhà Nico.", "For two weeks they play every afternoon at Nico's."),
  ("N", "Pero el día antes de la fiesta, Eva llama a Nico.", "Nhưng một ngày trước lễ hội, Eva gọi cho Nico.", "But the day before the festival, Eva calls Nico."),
  ("A", "Nico… no tengo voz.", "Nico ơi… mình mất giọng rồi.", "Nico… I've lost my voice."),
  ("B", "¿Qué? ¡No puede ser! ¡Mañana es la fiesta!", "Cái gì? Không thể nào! Mai là lễ hội rồi!", "What? It can't be! The festival is tomorrow!"),
  ("A", "Lo siento mucho. El médico dice que no debo hablar durante tres días.", "Mình xin lỗi lắm. Bác sĩ bảo mình không được nói trong ba ngày.", "I'm really sorry. The doctor says I mustn't talk for three days."),
  ("N", "Nico no sabe qué hacer. Sin Eva, la banda no tiene voz.", "Nico không biết phải làm sao. Không có Eva, ban nhạc chẳng còn giọng ca.", "Nico doesn't know what to do. Without Eva, the band has no voice."),
  ("N", "Esa noche, su abuela Amparo lo oye tocar solo y entra en su habitación.", "Tối hôm đó, bà nội Amparo nghe thấy Nico chơi đàn một mình và bước vào phòng cậu.", "That night his grandmother Amparo hears him playing alone and comes into his room."),
  ("N", "Amparo tiene 75 años. De joven, ella también tenía una banda.", "Bà Amparo 75 tuổi. Hồi trẻ, bà cũng từng có một ban nhạc.", "Amparo is 75. When she was young, she had a band too."),
  ("N", "«Yo sé todas vuestras canciones», le dice. «Las oigo cada tarde desde mi habitación».", "«Bà thuộc hết các bài của bọn cháu», bà bảo. «Chiều nào bà cũng nghe từ phòng bà».", "\"I know all your songs,\" she tells him. \"I hear them every afternoon from my room.\""),
  ("B", "Abuela, ¿estás loca?", "Bà ơi, bà đùa cháu à?", "Grandma, are you crazy?"),
  ("N", "Pero cuando Amparo abre la boca, Nico no puede creerlo: tiene una voz maravillosa.", "Nhưng khi bà Amparo cất giọng, Nico không tin nổi: bà có một giọng hát tuyệt vời.", "But when Amparo opens her mouth, Nico can't believe it: she has a wonderful voice."),
  ("N", "El sábado, Los Locos suben al escenario con una abuela de 75 años.", "Thứ Bảy, Những Kẻ Điên bước lên sân khấu cùng một bà cụ 75 tuổi.", "On Saturday, Los Locos go up on stage with a 75-year-old grandmother."),
  ("N", "La gente no cree lo que ve. Muchos sacan fotos con el móvil.", "Mọi người không tin vào mắt mình. Nhiều người lấy điện thoại ra chụp ảnh.", "People can't believe what they see. Lots of them take photos with their phones."),
  ("N", "La primera canción es hermosa, y todo el pueblo escucha sin hablar.", "Bài đầu tiên rất hay, cả làng lặng im lắng nghe.", "The first song is beautiful, and the whole village listens without a word."),
  ("N", "Después de la última canción, todos piden otra. Es una escena increíble.", "Sau bài cuối, mọi người đòi hát thêm bài nữa. Thật là một cảnh tượng khó tin.", "After the last song, everyone asks for another. It's an incredible scene."),
  ("B", "Abuela, ¿quieres ser un miembro de la banda?", "Bà ơi, bà có muốn làm thành viên của ban nhạc không?", "Grandma, do you want to be a member of the band?"),
  ("N", "Amparo acepta. «Pero yo elijo las canciones», dice.", "Bà Amparo đồng ý. «Nhưng bà là người chọn bài», bà nói.", "Amparo accepts. \"But I choose the songs,\" she says."),
  ("N", "Así empezó la carrera de Amparo, a los 75 años.", "Sự nghiệp ca hát của bà Amparo bắt đầu như thế, ở tuổi 75.", "That is how Amparo's career began, at the age of 75.")],
 [("locate", "Vì sao Eva không thể biểu diễn?", "Why can't Eva perform?", [("Vì cô ấy mất giọng", "Because she has lost her voice"), ("Vì cô ấy đi du lịch", "Because she is travelling"), ("Vì cô ấy không thích lễ hội", "Because she doesn't like the festival")], 0),
  ("locate", "Bà Amparo bao nhiêu tuổi?", "How old is Amparo?", [("17 tuổi", "17"), ("57 tuổi", "57"), ("75 tuổi", "75")], 2),
  ("infer", "Vì sao bà Amparo thuộc hết các bài của ban nhạc?", "Why does Amparo know all the band's songs?", [("Vì bà đã viết các bài ấy", "Because she wrote them"), ("Vì chiều nào bà cũng nghe cả nhóm tập ở nhà", "Because she heard the band practise at home every afternoon"), ("Vì Eva dạy bà", "Because Eva taught her")], 1)],
 names=["Nico", "Eva", "Amparo", "Los", "Locos"],
 token_map={"siento": "es:w:sentir", "creerlo": "es:w:creer"}))

lib.write_batch("03", S)
